// Three-set Venn diagram for inclusion-exclusion.
//
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(175,241);
real r = 1.2;
real d = 1.0;
pair A = (0,0);
pair B = (d,0);
pair C = (d/2, sqrt(3)/2*d);
draw(circle(A,r), black+1.5);
draw(circle(B,r), black+1.5);
draw(circle(C,r), black+1.5);
label("$A$", A + (-r*0.8, r*0.8), NW);
label("$B$", B + (r*0.8, r*0.8), NE);
label("$C$", C + (0, r*1.1), N);
label("$|A|+|B|+|C|$", (d/2, -r*1.3), S);
label("$-|A\cap B|-|B\cap C|-|C\cap A|$", (d/2, -r*1.6), S);
label("$+|A\cap B\cap C|$", (d/2, -r*1.9), S);
label("Each region counted exactly once", (d/2, -r*2.2), S);

// Stars and bars for x1 + x2 + x3 = 7.
// A two-argument size call bounds the output under Asymptote's default keepAspect
// and does not scale labels, so the compiler decides the box. This declaration is
// restated from a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(400,150);
real starR = 0.12;
real y = 0;
int n = 7, k = 3;
int bars = k - 1;
int total = n + bars;
int[] config = {0,0,1,0,0,0,1,0,0};
for (int i = 0; i < total; ++i) {
  real x = i;
  if (config[i] == 0) {
    filldraw(circle((x,y), starR), yellow, black);
  } else {
    draw((x, y+0.2)--(x, y-0.2), black+2);
  }
}
label("$x_1=2$", (1, -1.2), S);
label("$x_2=3$", (4, -1.2), S);
label("$x_3=2$", (7, -1.2), S);
label("stars and bars: $\binom{7+3-1}{3-1} = \binom{9}{2} = 36$", (4, 2.3), N);
